        state.non_form_errors = self.error_class(
            e.error_list,
            error_class="nonform",
            renderer=self.renderer,
        )

def _finish_async_validation(self, state):
    state.finalized = True
    state.result = self._verdict(state.errors, state.non_form_errors)
